{"function": "() => {
    const article = document.querySelector('article');
    if (!article) return '';
    // Get all child nodes of article, but we want the main content div maybe after the first few elements.
    // The content is under article > div > div > ... Let's find the div with class 'content' or similar.
    // We'll just get all text nodes within article, but exclude certain elements.
    const clone = article.cloneNode(true);
    // Remove script, style, button, a, img, nav, footer, .hidden, .sr-only
    const unwantedSelectors = 'script, style, button, a, img, nav, footer, .hidden, .sr-only, .license-info, .page-footer, .breadcrumbs';
    unwantedSelectors.split(', ').forEach(selector => {
        clone.querySelectorAll(selector).forEach(el => el.remove());
    });
    // Get text content, preserve line breaks a bit.
    const walker = document.createTreeWalker(clone, NodeFilter.SHOW_TEXT, null, false);
    let text = '';
    let node;
    while (node = walker.nextNode()) {
        const parent = node.parentElement;
        if (parent.tagName === 'LI' || parent.tagName === 'P' || parent.tagName === 'DIV') {
            text += node.textContent + '\\n';
        } else {
            text += node.textContent;
        }
    }
    // Clean up excessive whitespace
    text = text.replace(/\\s\\s+/g, ' ').replace(/\\n\\s*\\n/g, '\\n\\n').trim();
    return text;
}"}

